-- Carga de la lista oficial de precios Rappi desde "MENU DODO FINAL (3).xlsx", hoja Sheet3 ("Precio Rappi nuevo").
-- Ejecutar después de la migración 20261029120000_precios_rappi.sql y su PRUEBAS OK.
-- Fecha de vigencia editable abajo (por omisión 2026-10-29). Volver a correrla con la misma fecha reemplaza los precios.
-- Cada renglón se liga por nombre exacto a los productos del catálogo; pizzas a masa tradicional y delgada (T).
-- No se cargan (7):
--   · Trio Ganador ($610): combo propio de Rappi, no existe en el catálogo
--   · Mix Perfecto ($448): combo propio de Rappi, no existe en el catálogo
--   · Completo y Dulce ($249): combo propio de Rappi, no existe en el catálogo
--   · Dodster GO ($129): combo propio de Rappi, no existe en el catálogo
--   · GO BIG ($249): combo propio de Rappi, no existe en el catálogo
--   · El de Siempre ($265): combo propio de Rappi, no existe en el catálogo
--   · Supremo ($299): combo propio de Rappi, no existe en el catálogo
begin;
do $carga$
declare a uuid; fecha date := '2026-10-29'; r jsonb;
begin
  select id into a from perfiles where activo and rol::text='admin' limit 1;
  if a is null then raise exception 'FALTAN DATOS: un administrador activo.'; end if;
  perform set_config('request.jwt.claims',json_build_object('sub',a,'role','authenticated')::text,true);
  r := cargar_precios_rappi(fecha,'MENU DODO FINAL (3).xlsx · Sheet3',$renglones$[{"renglon":"Pepperoni 30 cm","nombres":["Pepperoni Mediano","Pepperoni Mediano T"],"precio":159},{"renglon":"Pepperoni 35 cm","nombres":["Pepperoni Grande","Pepperoni Grande T"],"precio":189},{"renglon":"BBQ Carne Supreme 30 cm","nombres":["BBQ Carne Supreme Mediano","BBQ Carne Supreme Mediano T"],"precio":279},{"renglon":"BBQ Carne Supreme 35 cm","nombres":["BBQ Carne Supreme Grande","BBQ Carne Supreme Grande T"],"precio":319},{"renglon":"Carbonara 30 cm","nombres":["Carbonara Mediano","Carbonara Mediano T"],"precio":279},{"renglon":"Carbonara 35 cm","nombres":["Carbonara Grande","Carbonara Grande T"],"precio":319},{"renglon":"Cheeseburger 30 cm","nombres":["Cheeseburger Mediano","Cheeseburger Mediano T"],"precio":279},{"renglon":"Cheeseburger 35 cm","nombres":["Cheeseburger Grande","Cheeseburger Grande T"],"precio":319},{"renglon":"Dodo Supreme 30 cm","nombres":["Dodo Supreme Mediano","Dodo Supreme Mediano T"],"precio":279},{"renglon":"Dodo Supreme 35 cm","nombres":["Dodo Supreme Grande","Dodo Supreme Grande T"],"precio":319},{"renglon":"Pollo hawai supreme 30 cm","nombres":["Pollo hawai supreme Mediano","Pollo hawai supreme Mediano T"],"precio":279},{"renglon":"Pollo hawai supreme 35 cm","nombres":["Pollo hawai supreme Grande","Pollo hawai supreme Grande T"],"precio":319},{"renglon":"Jamon y Champiñonas 30 cm","nombres":["Jamón y champiñones Mediano","Jamón y champiñones Mediano T"],"precio":199},{"renglon":"Jamon y Champiñonas 35 cm","nombres":["Jamón y champiñones Grande","Jamón y champiñones Grande T"],"precio":239},{"renglon":"Margherita 30 cm","nombres":["Margarita Mediano","Margarita Mediano T"],"precio":199},{"renglon":"Margherita 35 cm","nombres":["Margarita Grande","Margarita Grande T"],"precio":239},{"renglon":"HawaiI 30 cm","nombres":["Hawaiana Mediano","Hawaiana Mediano T"],"precio":239},{"renglon":"HawaiI 35 cm","nombres":["Hawaiana Grande","Hawaiana Grande T"],"precio":279},{"renglon":"Tres carnes 30 cm","nombres":["Tres Carnes Mediano","Tres Carnes Mediano T"],"precio":239},{"renglon":"Tres carnes 35 cm","nombres":["Tres Carnes Grande","Tres Carnes Grande T"],"precio":279},{"renglon":"Pollo Ranch 30 cm","nombres":["Pollo Ranch Mediano","Pollo Ranch Mediano T"],"precio":239},{"renglon":"Pollo Ranch 35 cm","nombres":["Pollo Ranch Grande","Pollo Ranch Grande T"],"precio":279},{"renglon":"Quatro Estaciones 30 cm","nombres":["Quatro estaciones Mediano","Quatro estaciones Mediano T"],"precio":239},{"renglon":"Quatro Estaciones 35 cm","nombres":["Quatro estaciones Grande","Quatro estaciones Grande T"],"precio":279},{"renglon":"4 quesos 30 cm","nombres":["Quatro quesos Mediano","Quatro quesos Mediano T"],"precio":239},{"renglon":"4 quesos 35 cm","nombres":["Quatro quesos Grande","Quatro quesos Grande T"],"precio":279},{"renglon":"Spicy Ranch 30 cm","nombres":["Ranch Picante Mediano","Ranch Picante Mediano T"],"precio":239},{"renglon":"Spicy Ranch 35 cm","nombres":["Ranch Picante Grande","Ranch Picante Grande T"],"precio":279},{"renglon":"Verduras y Champiñonas 30 cm","nombres":["Verduras y Champiñones Mediano","Verduras y Champiñones Mediano T"],"precio":239},{"renglon":"Verduras y Champiñonas 35 cm","nombres":["Verduras y Champiñones Grande","Verduras y Champiñones Grande T"],"precio":279},{"renglon":"Dodster Buffalo","nombres":["Dodster Buffalo","Dodster Buffalo 1 pza"],"precio":102},{"renglon":"Dodster cheesy spicy","nombres":["Dodster Cheesy Spicy","Dodster Cheesy Spicy 1 pza"],"precio":102},{"renglon":"Dodster chimichurri","nombres":["Dodster Chimichurri","Dodster Chimichurri 1 pza"],"precio":102},{"renglon":"Dodster Classico","nombres":["Dodster Classico","Dodster Classico 1 pza"],"precio":102},{"renglon":"Papas francesas 120 gramos","nombres":["Papas francesas Medium","Papas francesas Mediano","Papas francesas 120 g"],"precio":65},{"renglon":"Papas francesas 240 gramos","nombres":["Papas francesas Grande","Papas francesas 240 g"],"precio":85},{"renglon":"Papas Gajo 120 gramos","nombres":["Papas Gajo Medium","Papas Gajo Mediano","Papas Gajo 120 g"],"precio":65},{"renglon":"Papas Gajo 240 gramos","nombres":["Papas Gajo Grande","Papas Gajo 240 g"],"precio":85},{"renglon":"Alitas Buffalo 10 alitas","nombres":["Alitas Buffalo","Alitas Buffalo 10 uds","Alitas Buffalo 7 uds"],"precio":210},{"renglon":"Boneless 120 gramos","nombres":["Boneless Medium","Boneless M"],"precio":199},{"renglon":"Rolls de manzana 8 piezas","nombres":["Rolls con manzana 8","Rolls con manzana 8 piezas","Rolls de manzana 8","Rolls de manzana 8 piezas"],"precio":65},{"renglon":"Rolls con piña 8 piezas","nombres":["Rolls con piña 8","Rolls con piña 8 piezas"],"precio":65},{"renglon":"Familia Coca 600 ml","nombres":["Coca-Cola 0,6 L","Coca-Cola 600 ml","Coca Cola 0,6 L","Coca Cola 600 ml","Coca Light 0,6 L","Coca Light 600 ml","Coca Zero 0,6 L","Coca Zero 600 ml","Sprite 0,6 L","Sprite 600 ml","Fanta 0,6 L","Fanta 600 ml","Sidral mundet 0,6 L","Sidral mundet 600 ml"],"precio":41},{"renglon":"Familia Coca 2 Litros","nombres":["Coca-Cola 2 L","Coca-Cola 2 Litros","Coca Cola 2 L","Coca Cola 2 Litros","Coca Light 2 L","Coca Light 2 Litros","Coca Zero 2 L","Coca Zero 2 Litros","Sprite 2 L","Sprite 2 Litros","Fanta 2 L","Fanta 2 Litros","Sidral mundet 2 L","Sidral mundet 2 Litros"],"precio":71},{"renglon":"Fuze tea","nombres":["Fuze tea","Fuze tea 0,6 L","Fuze tea 600 ml"],"precio":41},{"renglon":"Dip de BBQ","nombres":["Dip BBQ","Dip BBQ Dip","Dip de BBQ"],"precio":27},{"renglon":"Dip de Ranch","nombres":["Dip Ranch","Dip Ranch Dip","Dip de Ranch"],"precio":27},{"renglon":"Dip de Buffalo","nombres":["Dip Buffalo","Dip Buffalo Dip","Dip de Buffalo"],"precio":27},{"renglon":"Dip de Mango Habanero","nombres":["Dip Mango Habanero","Dip Mango Habanero Dip","Dip de Mango Habanero"],"precio":27}]$renglones$::jsonb);
  drop table if exists carga_precios_rappi; create temp table carga_precios_rappi as select r;
end $carga$;
commit;

-- Resultado: primero los renglones del menú que no encontraron producto (mándaselos a Claude), luego lo cargado.
select 'SIN PRODUCTO' as resultado, s as producto, null::numeric as precio, null::date as vigente_desde
from carga_precios_rappi, jsonb_array_elements_text(r->'sin_producto') s
union all
select 'CARGA OK', p.nombre, x.precio, x.vigente_desde
from precios_rappi x join productos_venta p using(dodo_id)
where x.fuente='MENU DODO FINAL (3).xlsx · Sheet3' and x.vigente_desde=(select max(vigente_desde) from precios_rappi where fuente='MENU DODO FINAL (3).xlsx · Sheet3')
order by 1 desc, 2;
